WITH TIPO_PESO_CORRETO AS (    SELECT V.CODPARC, TA.TIPO_PESO    FROM VINCULO_PARCEIRO_TIPO V JOIN TIPO_ARMAZENAGEM TA ON V.ID_TIPO_ARMAZENAGEM = TA.ID    WHERE V.CODPARC = :VAR_PARCEIRO_SELECIONADO    ORDER BY V.ID DESC LIMIT 1),ENTRADAS_PERIODO AS (    SELECT IFNULL(SUM(CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN I.PESO_ITEM_LIQ ELSE I.PESO_ITEM END), 0) AS VALOR    FROM GESTAO_NOTAS_APROVACAO G    JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA    JOIN TIPO_PESO_CORRETO TPC ON G.CODPARC = TPC.CODPARC    WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO AND G.ENTREGUE = 1 AND G.DATA_ENTREGA BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM),SAIDAS_PERIODO AS (    SELECT IFNULL(SUM(CASE WHEN TPC.TIPO_PESO = 'Líquido' THEN N.PESO_ITEM_LIQ ELSE N.PESO_ITEM END), 0) AS VALOR    FROM IMP_NOTAS_ARMAZ N    JOIN TIPO_PESO_CORRETO TPC ON N.CODPARC = TPC.CODPARC    WHERE N.CODPARC = :VAR_PARCEIRO_SELECIONADO AND N.ATUALESTOQUE = 1 AND N.DTNEG BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM)SELECT    (SELECT VALOR FROM ENTRADAS_PERIODO) AS ENTRADAS,    (SELECT VALOR FROM SAIDAS_PERIODO) AS SAIDAS,    (SELECT VALOR FROM ENTRADAS_PERIODO) - (SELECT VALOR FROM SAIDAS_PERIODO) AS SALDO